<?php
use Illuminate\Support\Facades\DB;
require dirname(__DIR__).'/vendor/autoload.php';$app=require dirname(__DIR__).'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();$db=DB::connection();if(!$app->isLocal()||$db->getDatabaseName()!=='water_billing_systems'||$db->getConfig('host')!=='127.0.0.1')throw new RuntimeException('Unexpected database');$db->statement('SET TRANSACTION READ ONLY');$db->beginTransaction();foreach($db->table('consumers')->whereIn('meter_number',['MT-3333','MT-7777','MT-0909','MT-9191'])->orderBy('meter_number')->get() as $consumer){echo "ACCOUNT ",json_encode($consumer),PHP_EOL;foreach($db->table('meter_readings')->where('consumer_id',$consumer->id)->orderBy('reading_date')->orderBy('id')->get() as $reading){echo "READING ",json_encode($reading),PHP_EOL;foreach($db->table('bills')->where('meter_reading_id',$reading->id)->get() as $bill)echo "BILL ",json_encode($bill),PHP_EOL;}foreach($db->table('bills')->where('consumer_id',$consumer->id)->whereNull('meter_reading_id')->orderBy('billing_period')->get() as $bill)echo "UNLINKED BILL ",json_encode($bill),PHP_EOL;foreach($db->table('payments')->where('consumer_id',$consumer->id)->orderBy('id')->get() as $payment)echo "PAYMENT ",json_encode($payment),PHP_EOL;}
$db->rollBack(0);
